def trend(xs):
    pairs = list(zip(xs, xs[1:]))
    if not pairs:
        return 0
    if all(a < b for a, b in pairs):
        return 1
    if all(a > b for a, b in pairs):
        return -1
    return 0

def largest_gap(xs):
    s = sorted(xs)
    return max((b - a for a, b in zip(s, s[1:])), default=0)

def orders_to_fill(sizes, target):
    if target <= 0:
        return 0
    filled = 0
    for count, size in enumerate(sorted(sizes, reverse=True), 1):
        filled += size
        if filled >= target:
            return count
    return -1

from bisect import bisect_left, bisect_right


def count_in_range(xs, lo, hi):
    if hi < lo:
        return 0
    return bisect_right(xs, hi) - bisect_left(xs, lo)

def depth_sum(x, depth=1):
    total = 0
    for v in x:
        if isinstance(v, list):
            total += depth_sum(v, depth + 1)
        else:
            total += v * depth
    return total

